cd /tmp/probe/lines && cat > fitstroke.py <<'EOF'
import sys, math
sys.path.insert(0, '/tmp/probe')
import png
w,h,ch,ct,px,chunks = png.load(sys.argv[1])
bg = px[0:3]
actual=set()
for y in range(h):
    for x in range(w):
        if px[(y*w+x)*ch:(y*w+x)*ch+ch]!=bg: actual.add((x,y))

def render(ax,ay,bx,by,sw,cap):
    dx,dy=bx-ax,by-ay
    L=math.hypot(dx,dy); ux,uy=dx/L,dy/L; vx,vy=-uy,ux
    hw=sw/2.0
    ext = hw if cap=='square' else 0.0
    res=set()
    x0=int(min(ax,bx)-hw-2); x1=int(max(ax,bx)+hw+2)
    y0=int(min(ay,by)-hw-2); y1=int(max(ay,by)+hw+2)
    for Y in range(y0,y1+1):
        for X in range(x0,x1+1):
            px_,py_=X+0.5,Y+0.5
            t=(px_-ax)*ux+(py_-ay)*uy
            s=(px_-ax)*vx+(py_-ay)*vy
            if -ext<=t<=L+ext and abs(s)<=hw: res.add((X,Y))
    return res

best=None
import itertools
# search around ax~468.5,ay~471, bx~407.5,by~669, w~24.8
for ax in [466+i*0.5 for i in range(9)]:
 for ay in [469+i*0.5 for i in range(9)]:
  for bx in [405+i*0.5 for i in range(9)]:
   for by in [667+i*0.5 for i in range(9)]:
    for sw in [23+i*0.5 for i in range(9)]:
     for cap in ['square','butt']:
        r=render(ax,ay,bx,by,sw,cap)
        d=len(r.symmetric_difference(actual))
        if best is None or d<best[0]: best=(d,ax,ay,bx,by,sw,cap)
print(best)
EOF
