args.command:
cd /tmp/probe/lines && cat > pqfit.py <<'EOF'
import sys
sys.path.insert(0, '/tmp/probe')
import png
path=sys.argv[1]; y0=int(sys.argv[2]); y1=int(sys.argv[3])
w,h,ch,ct,px,chunks = png.load(path)
bg = px[0:3]
actual=set()
for y in range(y0,min(y1,h-1)+1):
    for x in range(w):
        if px[(y*w+x)*ch:(y*w+x)*ch+ch]!=bg: actual.add((x,y))
miny=min(y for x,y in actual); maxy=max(y for x,y in actual)
# coarse vertex estimates
def xr(y):
    xs=[x for x,yy in actual if yy==y]; return min(xs),max(xs)
tl=xr(miny); bl=xr(maxy)
# model: parallelogram, horizontal caps: top edge y=yt from xt0..xt1; bottom edge y=yb from xb0..xb1
def render(yt,xt0,xt1,yb,xb0,xb1):
    res=set()
    for Y in range(int(yt)-2,int(yb)+3):
        cy=Y+0.5
        if cy<yt or cy>yb: continue
        f=(cy-yt)/(yb-yt)
        xa=xt0+(xb0-xt0)*f; xb=xt1+(xb1-xt1)*f
        X=int(min(xa,xb))
        while X<=max(xa,xb)+1:
            if X+0.5>=xa and X+0.5<=xb: res.add((X,Y))
            X+=1
    return res
best=None
import itertools
step=0.25
def rng(c): 
    return [c-1+i*step for i in range(9)]
for yt in rng(miny+0.5):
 for yb in rng(maxy+0.5):
  for xt0 in rng(tl[0]+0.5):
   for xt1 in rng(tl[1]+0.5):
    for xb0 in rng(bl[0]+0.5):
     for xb1 in rng(bl[1]+0.5):
        r=render(yt,xt0,xt1,yb,xb0,xb1)
        d=len(r.symmetric_difference(actual))
        if best is None or d<best[0]: best=(d,yt,xt0,xt1,yb,xb0,xb1)
print("best mismatch",best[0])
d,yt,xt0,xt1,yb,xb0,xb1=best
print("top edge y=%.2f x %.2f..%.2f ; bottom y=%.2f x %.2f..%.2f"%(yt,xt0,xt1,yb,xb0,xb1))
EOF
